function openDb(){
  return new Promise((resolve,reject)=>{
    const r=indexedDB.open(DB_NAME,DB_VERSION);
    r.onupgradeneeded=(event)=>{
      const d=r.result,tx=r.transaction;
      const ensure=(name,options)=>d.objectStoreNames.contains(name)?tx.objectStore(name):d.createObjectStore(name,options);
      ensure('profile',{keyPath:'id'});
      ensure('farms',{keyPath:'id'});
      const places=ensure('places',{keyPath:'id'});
      if(!places.indexNames.contains('farmId'))places.createIndex('farmId','farmId');
      if(!places.indexNames.contains('type'))places.createIndex('type','type');
      const boundaries=ensure('boundaries',{keyPath:'id'});
      if(!boundaries.indexNames.contains('placeId'))boundaries.createIndex('placeId','placeId',{unique:true});
      const seasons=ensure('seasons',{keyPath:'id'});
      if(!seasons.indexNames.contains('placeId'))seasons.createIndex('placeId','placeId');
      const observations=ensure('observations',{keyPath:'id'});if(!observations.indexNames.contains('placeId'))observations.createIndex('placeId','placeId');
      const samples=ensure('ag_samples',{keyPath:'id'});if(!samples.indexNames.contains('placeId'))samples.createIndex('placeId','placeId');
      const experiments=ensure('experiments',{keyPath:'id'});if(!experiments.indexNames.contains('placeId'))experiments.createIndex('placeId','placeId');if(!experiments.indexNames.contains('farmId'))experiments.createIndex('farmId','farmId');const applications=ensure('applications',{keyPath:'id'});if(!applications.indexNames.contains('placeId'))applications.createIndex('placeId','placeId');if(!applications.indexNames.contains('farmId'))applications.createIndex('farmId','farmId');const harvests=ensure('harvests',{keyPath:'id'});if(!harvests.indexNames.contains('placeId'))harvests.createIndex('placeId','placeId');if(!harvests.indexNames.contains('farmId'))harvests.createIndex('farmId','farmId');const weather=ensure('weather_snapshots',{keyPath:'id'});if(!weather.indexNames.contains('farmId'))weather.createIndex('farmId','farmId');const refs=ensure('reference_layers',{keyPath:'id'});if(!refs.indexNames.contains('farmId'))refs.createIndex('farmId','farmId');const sharing=ensure('sharing',{keyPath:'id'});if(!sharing.indexNames.contains('placeId'))sharing.createIndex('placeId','placeId',{unique:true});
      const events=ensure('events',{keyPath:'id'});
      if(!events.indexNames.contains('placeId'))events.createIndex('placeId','placeId');
      const media=ensure('media',{keyPath:'id'});
      if(!media.indexNames.contains('placeId'))media.createIndex('placeId','placeId');
      if(!media.indexNames.contains('eventId'))media.createIndex('eventId','eventId');
      const tasks=ensure('tasks',{keyPath:'id'});
      if(!tasks.indexNames.contains('placeId'))tasks.createIndex('placeId','placeId');
      if(!tasks.indexNames.contains('dueDate'))tasks.createIndex('dueDate','dueDate');
      const outboxStore=ensure('outbox',{keyPath:'mutationId'});

      if(event.oldVersion<2){
        if(d.objectStoreNames.contains('fields')){
          const legacy=tx.objectStore('fields');
          legacy.openCursor().onsuccess=(e)=>{
            const c=e.target.result;
            if(!c)return;
            places.put(migrateLegacyFieldRecord(c.value));
            c.continue();
          };
        }
        for(const name of ['boundaries','seasons','events','media']){
          if(!d.objectStoreNames.contains(name))continue;
          const store=tx.objectStore(name);
          store.openCursor().onsuccess=(e)=>{
            const c=e.target.result;
            if(!c)return;
            const value=c.value;
            if(!value.placeId&&value.fieldId)c.update({...value,placeId:value.fieldId});
            c.continue();
          };
        }
        outboxStore.openCursor().onsuccess=(e)=>{
          const c=e.target.result;
          if(!c)return;
          c.update(migrateLegacyOutboxMutation(c.value));
          c.continue();
        };
      }
    };
    r.onblocked=()=>reject(new Error('CropChronicle update is blocked by another open tab. Close other CropChronicle tabs and reopen.'));
    r.onsuccess=()=>{
      const opened=r.result;
      opened.onversionchange=()=>opened.close();
      resolve(opened);
    };
    r.onerror=()=>reject(r.error);
  });
}
function req(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function done(tx){return new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error??new Error('IndexedDB transaction aborted.'));});}
async function all(store){const tx=db.transaction(store);return req(tx.objectStore(store).getAll());}
async function one(store,id){const tx=db.transaction(store);return req(tx.objectStore(store).get(id));}
async function byIndex(store,index,value){const tx=db.transaction(store);return req(tx.objectStore(store).index(index).getAll(value));}
async function putProfile(record){const tx=db.transaction('profile','readwrite');tx.objectStore('profile').put(record);await done(tx);}
async function putWithOutbox(entityType,entity,{operation='create',baseVersion=null}={}){const store=ENTITY_STORES[entityType];const mutation=makeOutboxMutation(entityType,entity,operation,baseVersion);const tx=db.transaction([store,'outbox'],'readwrite');tx.objectStore(store).put(entity);tx.objectStore('outbox').put(mutation);await done(tx);return mutation;}
function notifySaved(){const el=$('#saveToast');el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},2200);}
function localDateOnly(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function placeTypeLabel(type){return type==='herd/pen'?'Herd / pen':type.charAt(0).toUpperCase()+type.slice(1);}

async function compressImage(file){const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(new Error('Could not read photo.'));el.src=url;});const target=fitWithin(img.naturalWidth,img.naturalHeight,PHOTO_MAX_EDGE);const canvas=document.createElement('canvas');canvas.width=target.width;canvas.height=target.height;canvas.getContext('2d',{alpha:false}).drawImage(img,0,0,target.width,target.height);const blob=await new Promise((resolve,reject)=>canvas.toBlob((b)=>b?resolve(b):reject(new Error('Compression failed')),'image/jpeg',PHOTO_JPEG_QUALITY));return {blob,width:target.width,height:target.height,mimeType:'image/jpeg'};}finally{URL.revokeObjectURL(url);}}
async function buildBackup(){const data={};for(const store of STORES){data[store]=await Promise.all((await all(store)).map(serialize));}return buildBackupEnvelope(data,new Date().toISOString());}
async function serialize(record){
  if(record===null||typeof record!=='object')return record;
  if(Array.isArray(record))return Promise.all(record.map(serialize));
  const copy={};
  for(const [key,value] of Object.entries(record)){
    if(key==='blob'&&value instanceof Blob){
      copy.blobDataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(value);});
    }else copy[key]=await serialize(value);
  }
  return copy;
}
async function downloadBackup(){const exportedAt=now();const payload=await buildBackup();payload.exportedAt=exportedAt;const json=JSON.stringify(payload,null,2);const filename=`cropchronicle-backup-${exportedAt.slice(0,10)}.json`;const blob=new Blob([json],{type:'application/json'});let shared=false;try{const file=new File([blob],filename,{type:'application/json'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'CropChronicle backup'});shared=true;}}catch(error){if(error?.name==='AbortError')return;}if(!shared){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}const meta=await getMeta();await putProfile({...meta,id:'meta',lastBackupAt:exportedAt,appVersion:APP_VERSION});await refreshBackupStatus();}
async function getMeta(){return (await one('profile','meta'))??{id:'meta'};}
async function getSetup(){return (await one('profile','setup'))??{id:'setup'};}
