async function refreshPlaces(){const places=state.farmId?await byIndex('places','farmId',state.farmId):[];if(!places.some((p)=>p.id===state.placeId))state.placeId=places[0]?.id??null;$('#places').innerHTML=places.map((p)=>`<button class="row place" data-id="${p.id}"><strong>${esc(p.name)}</strong><small>${esc(placeTypeLabel(p.type))}${p.acreage?` · ${p.acreage} acres`:''}</small></button>`).join('')||'<p class="muted">Choose a farm, then add a Place.</p>';document.querySelectorAll('.place').forEach((el)=>el.addEventListener('click',async()=>{state.placeId=el.dataset.id;await refreshTimeline();}));await refreshTimeline();await fillTaskPlaces();}
let timelineRevision=0,timelinePhotoUrls=[];
async function refreshTimeline(){
  const revision=++timelineRevision,placeId=state.placeId;
  const [events,photos,place]=await Promise.all([
    placeId?byIndex('events','placeId',placeId):[],
    placeId?byIndex('media','placeId',placeId):[],
    placeId?one('places',placeId):null,
  ]);
  if(revision!==timelineRevision)return;
  for(const url of timelinePhotoUrls)URL.revokeObjectURL(url);
  timelinePhotoUrls=[];
  $('#chroniclePlaceLabel').textContent=place?`${place.name} · ${placeTypeLabel(place.type)}`:'Choose a Place';
  const entries=[...events,...photos.map((photo)=>({...photo,occurredAt:photo.createdAt,localPhoto:true}))];
  $('#timeline').innerHTML=sortTimeline(entries).map((entry)=>{
    if(entry.localPhoto){
      if(!(entry.blob instanceof Blob))return '<article class="event">Photo unavailable on this phone.</article>';
      const url=URL.createObjectURL(entry.blob);timelinePhotoUrls.push(url);
      return `<article class="event"><time>${esc(new Date(entry.createdAt).toLocaleString())}</time><strong>Photo</strong><img class="chronicle-photo" src="${url}" alt="Saved photo for this Place" loading="lazy"></article>`;
    }
    return `<article class="event"><time>${esc(new Date(entry.occurredAt).toLocaleString())}</time><strong>${esc(entry.eventType)}</strong><span>${esc(entry.title||entry.notes||'')}</span></article>`;
  }).join('')||'<p class="muted">Choose a Place to see its Chronicle.</p>';
}
async function currentSeason(placeId){const xs=placeId?await byIndex('seasons','placeId',placeId):[];return xs.sort((a,b)=>String(b.year??'').localeCompare(String(a.year??'')))[0]??null;}
async function refreshAlmanac(){const weather=state.farmId?await byIndex('weather_snapshots','farmId',state.farmId):[],refs=state.farmId?await byIndex('reference_layers','farmId',state.farmId):[],latest=weather.slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0]??null,cards=[];if(latest){const temp=latest.values?.temperature,frost=frostContext({temperature:temp});cards.push(almanacCard({kind:'measured',title:'Latest field weather',value:temp===null?'Temperature not recorded':temp+' °F',detail:frost.message,provenance:latest.provenance}));const flags=sprayWeatherFlags({windSpeed:latest.values?.windSpeed,windGust:latest.values?.windGust,precipitation:latest.values?.precipitation,temperature:temp});if(flags.length)cards.push(almanacCard({kind:'measured',title:'Application-weather checks',detail:flags.map(x=>x.message).join(' '),provenance:latest.provenance}));}for(const ref of refs.slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,6))cards.push(almanacCard({kind:ref.kind,title:ref.title,detail:ref.detail,provenance:ref.provenance}));$('#almanacCards').innerHTML=cards.map(c=>{const fresh=c.provenance?sourceFreshness(c.provenance):'unknown',traditional=c.kind==='traditional';return '<article class="intel-item '+(fresh==='stale'?'freshness-stale ':'')+(traditional?'traditional-card':'')+'"><span class="almanac-kind">'+esc(c.label)+'</span><strong>'+esc(c.title)+'</strong>'+(c.value?'<span>'+esc(c.value)+'</span>':'')+(c.detail?'<span>'+esc(c.detail)+'</span>':'')+'<div class="source-line">'+esc(c.provenance?.provider??'No external source')+(c.provenance?.retrievedAt?' · '+esc(new Date(c.provenance.retrievedAt).toLocaleString()):'')+(fresh==='stale'?' · STALE':'')+'</div></article>';}).join('')||'<article class="intel-item"><strong>Offline ready</strong><span>Add a weather observation or Almanac note. Online providers can feed this same sourced format later.</span></article>';}
async function refreshNwsWeather(){if(!state.location)throw new Error('Use Locate me first so CropChronicle knows which forecast point you requested.');$('#providerStatus').textContent='Refreshing National Weather Service forecast…';try{const result=await nwsPointForecast(state.location.lat,state.location.lon),period=result.periods?.[0];if(!period)throw new Error('No forecast period returned.');const snap=nwsPeriodToSnapshot(period,result.provenance,newId('weather')),createdAt=now(),record=createVersioned({...snap,farmId:state.farmId,createdAt,privacy:'private'},createdAt);await putWithOutbox('weather_snapshot',record);$('#providerStatus').textContent='NWS forecast refreshed. Farm GPS was used for this request; saved forecast is private.';await refreshAlmanac();}catch(error){const status=providerStatus(error);$('#providerStatus').textContent='NWS '+status.message+'. Existing farm records and last saved weather remain available.';$('#providerStatus').classList.add('provider-error');throw error;}}
