async function saveManualWeather(input){if(!state.farmId)throw new Error('Choose or create a farm first.');const createdAt=now(),provenance=buildAgProvenance({provider:'Farmer observation',kind:'farmer-entered',retrievedAt:createdAt,observedAt:createdAt}),snapshot=weatherSnapshot({id:newId('weather'),kind:'measured',temperature:input.temperature,humidity:input.humidity,windSpeed:input.windSpeed,windGust:input.windGust,precipitation:input.precipitation,provenance});const record=createVersioned({...snapshot,farmId:state.farmId,notes:String(input.notes||'').trim(),createdAt,privacy:'private'},createdAt);await putWithOutbox('weather_snapshot',record);notifySaved();await refreshAlmanac();}
