function renderBoundaryDraft(points=[]){if(state.geoMap){setBoundaryDraft(state.geoMap,points);$('#geoMap').hidden=false;$('#farmMap').classList.add('map-live');return;}const map=$('#fallbackMap');map.innerHTML='';if(!points.length)return;const lats=points.map(p=>p.lat),lons=points.map(p=>p.lon),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),latSpan=Math.max(maxLat-minLat,.0001),lonSpan=Math.max(maxLon-minLon,.0001);const toPct=p=>({x:5+90*(p.lon-minLon)/lonSpan,y:95-90*(p.lat-minLat)/latSpan});const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','boundary-svg');const poly=document.createElementNS('http://www.w3.org/2000/svg','polygon');poly.setAttribute('points',points.map(p=>{const q=toPct(p);return `${q.x},${q.y}`}).join(' '));svg.append(poly);map.append(svg);for(const p of points){const q=toPct(p),dot=document.createElement('span');dot.className='boundary-point';dot.style.left=q.x+'%';dot.style.top=q.y+'%';map.append(dot);}}
