async function refreshToday(){const tasks=await all('tasks'),places=await all('places'),placeMap=new Map(places.map((p)=>[p.id,p]));const grouped=groupTasksForToday(tasks,localDateOnly());renderTasks('#tasksOverdue',grouped.overdue,placeMap,true);renderTasks('#tasksToday',grouped.today,placeMap,false);renderTasks('#tasksNext7',grouped.next7,placeMap,false);}
function renderTasks(selector,tasks,placeMap,overdue){const el=$(selector);el.innerHTML=tasks.map((t)=>{const p=placeMap.get(t.placeId),repeat=t.repeat?.kind&&t.repeat.kind!=='none'?` · repeats ${repeatLabel(t.repeat)}`:'';return `<article class="task-card${overdue?' overdue':''}" data-task="${t.id}"><h4>${esc(t.title)}</h4><div class="task-meta">${esc(p?.name||'Place')} · due ${esc(t.dueDate)}${esc(repeat)}</div>${t.notes?`<p>${esc(t.notes)}</p>`:''}<div class="task-actions"><button class="task-done" data-id="${t.id}">Done</button>${t.repeat?.kind&&t.repeat.kind!=='none'?`<button class="task-skip skip" data-id="${t.id}">Skip</button>`:''}</div></article>`;}).join('')||'<p class="muted">Nothing here.</p>';el.querySelectorAll('.task-done').forEach((b)=>b.addEventListener('click',()=>completeTask(b.dataset.id)));el.querySelectorAll('.task-skip').forEach((b)=>b.addEventListener('click',()=>skipTask(b.dataset.id)));}
