async function completeTask(id){const tx=db.transaction(['tasks','events','outbox'],'readwrite'),tasks=tx.objectStore('tasks'),events=tx.objectStore('events'),outbox=tx.objectStore('outbox');const committed=done(tx);let task;try{task=await req(tasks.get(id));if(!task||task.status!=='open'){await committed;return;}const completedAt=now(),today=localDateOnly(),updated=updateVersioned(task,{status:'done',completedAt},completedAt),event=createVersioned({id:newId('event'),farmId:task.farmId,placeId:task.placeId,eventType:'task_done',occurredAt:completedAt,title:`Task done: ${task.title}`,notes:task.notes||'',privacy:'private',details:{taskId:task.id},createdAt:completedAt},completedAt);const nextDue=nextRepeatDue(task.dueDate,task.repeat,today);tasks.put(updated);events.put(event);outbox.put(makeOutboxMutation('task',updated,'update',task.version,completedAt));outbox.put(makeOutboxMutation('event',event,'create',null,completedAt));if(nextDue){const nextTask=createVersioned({id:newId('task'),seriesId:task.seriesId||task.id,farmId:task.farmId,placeId:task.placeId,title:task.title,dueDate:nextDue,repeat:task.repeat,notes:task.notes||'',status:'open',createdAt:completedAt},completedAt);tasks.put(nextTask);outbox.put(makeOutboxMutation('task',nextTask,'create',null,completedAt));}await committed;}catch(error){try{tx.abort();}catch{}await committed.catch(()=>{});throw error;}notifySaved();await refreshToday();if(state.placeId===task.placeId)await refreshTimeline();await refresh();}
