$('#addHarvest').addEventListener('click',()=>{if(!state.placeId)return alert('Choose a field first.');$('#harvestDate').value=new Date().toISOString().slice(0,10);$('#harvestDialog').showModal();});$('#cancelHarvest').addEventListener('click',()=>$('#harvestDialog').close());$('#harvestForm').addEventListener('submit',async(e)=>{e.preventDefault();try{await saveHarvest({harvestedAt:$('#harvestDate').value,amount:$('#harvestAmount').value,unit:$('#harvestUnit').value,acres:$('#harvestAcres').value,moisture:$('#harvestMoisture').value,notes:$('#harvestNotes').value});$('#harvestDialog').close();}catch(error){alert(error.message);}});
$('#addWeatherSnapshot').addEventListener('click',()=>$('#weatherDialog').showModal());$('#cancelWeather').addEventListener('click',()=>$('#weatherDialog').close());$('#weatherForm').addEventListener('submit',async(e)=>{e.preventDefault();try{await saveManualWeather({temperature:$('#weatherTemp').value,humidity:$('#weatherHumidity').value,windSpeed:$('#weatherWind').value,windGust:$('#weatherGust').value,precipitation:$('#weatherPrecip').value,notes:$('#weatherNotes').value});$('#weatherDialog').close();}catch(error){alert(error.message);}});
$('#addAlmanacNote').addEventListener('click',()=>$('#almanacNoteDialog').showModal());$('#cancelAlmanacNote').addEventListener('click',()=>$('#almanacNoteDialog').close());$('#almanacNoteForm').addEventListener('submit',async(e)=>{e.preventDefault();try{await saveAlmanacNote({kind:$('#almanacKind').value,title:$('#almanacTitle').value,detail:$('#almanacDetail').value,source:$('#almanacSource').value});$('#almanacNoteDialog').close();}catch(error){alert(error.message);}});
$('#setSeason').addEventListener('click',async()=>{if(!state.placeId)return alert('Choose a field or pasture first.');const current=await currentSeason(state.placeId);$('#seasonCrop').innerHTML=CROP_CATEGORIES.map(c=>'<option value="'+c+'">'+esc(CROP_VISUALS[c]?.label??c)+'</option>').join('');$('#seasonCrop').value=current?.crop??'corn';$('#seasonVariety').value=current?.variety??'';$('#seasonPlanted').value=current?.plantedAt??'';$('#seasonStatus').value=current?.status??'growing';$('#seasonNotes').value=current?.notes??'';$('#seasonDialog').showModal();});
$('#cancelSeason').addEventListener('click',()=>$('#seasonDialog').close());
$('#seasonForm').addEventListener('submit',async(e)=>{e.preventDefault();try{await saveSeason({crop:$('#seasonCrop').value,variety:$('#seasonVariety').value,plantedAt:$('#seasonPlanted').value,status:$('#seasonStatus').value,notes:$('#seasonNotes').value});$('#seasonDialog').close();}catch(error){alert(error.message);}});
$('#addScout').addEventListener('click',()=>{if(!state.placeId)return alert('Choose a field or pasture first.');$('#scoutNotes').value='';$('#scoutDialog').showModal();});
$('#cancelScout').addEventListener('click',()=>$('#scoutDialog').close());
$('#scoutForm').addEventListener('submit',async(e)=>{e.preventDefault();try{await saveScout({category:$('#scoutCategory').value,severity:$('#scoutSeverity').value,notes:$('#scoutNotes').value,useLocation:$('#scoutUseLocation').checked});$('#scoutDialog').close();}catch(error){alert(error.message);}});
$('#addFarm').addEventListener('click',async()=>{const name=prompt('Farm name');if(!name)return;await createFarmFrom(name,prompt('Region (optional)')||'');});
$('#addPlace').addEventListener('click',async()=>{if(!state.farmId)return alert('Choose or create a farm first.');const name=prompt('Place name');if(!name)return;const type=prompt('Type: field, greenhouse, barn, pasture, or herd/pen','field')||'field';if(!PLACE_TYPES.includes(type))return alert('Use: field, greenhouse, barn, pasture, or herd/pen.');await createPlaceFrom(name,type,prompt('Acres (optional)')||'');});
$('#addEvent').addEventListener('click',async()=>{if(!state.placeId||!state.farmId)return alert('Choose a farm and Place first.');await createEventFrom(prompt('Event type','observation')||'note',prompt('Short title')||'',prompt('Notes')||'');});
$('#photoInput').addEventListener('change',async(e)=>{if(!state.placeId||!state.farmId){e.target.value='';return alert('Choose a farm and Place first.');}const file=e.target.files?.[0];if(!file)return;const placeId=state.placeId,place=await one('places',placeId);if(!place)throw new Error('Choose a Place.');const c=await compressImage(file);const media=createVersioned({id:newId('media'),farmId:place.farmId,placeId,localName:file.name,mimeType:c.mimeType,width:c.width,height:c.height,blob:c.blob,createdAt:now()},now());await putWithOutbox('media',media);$('#photoStatus').textContent=`Saved on this phone at ${c.width}×${c.height}`;notifySaved();e.target.value='';await refresh();await refreshTimeline();});
$('#exportBackup').addEventListener('click',downloadBackup);$('#backupNow').addEventListener('click',downloadBackup);$('#showInstall').addEventListener('click',()=>$('#installGuide').showModal());$('#closeInstall').addEventListener('click',()=>$('#installGuide').close());

async function fillTaskPlaces(){const places=await all('places');$('#taskPlace').innerHTML=places.map((p)=>`<option value="${p.id}">${esc(p.name)} — ${esc(placeTypeLabel(p.type))}</option>`).join('');if(state.placeId)$('#taskPlace').value=state.placeId;}
$('#addTask').addEventListener('click',async()=>{await fillTaskPlaces();if(!$('#taskPlace').options.length)return alert('Add a Place before creating a task.');$('#taskDue').value=localDateOnly();$('#taskTitle').value='';$('#taskNotes').value='';$('#taskRepeat').value='none';$('#taskIntervalWrap').hidden=true;$('#taskDialog').showModal();});
$('#cancelTask').addEventListener('click',()=>$('#taskDialog').close());
$('#taskRepeat').addEventListener('change',()=>{$('#taskIntervalWrap').hidden=$('#taskRepeat').value!=='every_n_days';});
$('#taskForm').addEventListener('submit',async(e)=>{e.preventDefault();await createTaskFrom({title:$('#taskTitle').value.trim(),placeId:$('#taskPlace').value,dueDate:$('#taskDue').value,repeatKind:$('#taskRepeat').value,everyNDays:$('#taskInterval').value,notes:$('#taskNotes').value.trim()});$('#taskDialog').close();switchView('today');});

const installPictures=`<div class="install-pictures"><figure><div class="phone-pic"><div class="safari-bar">cropchronicle.pages.dev</div><div class="share-box">⇧</div></div><figcaption>Tap Safari's Share button.</figcaption></figure><figure><div class="phone-pic"><div class="menu-line">Copy</div><div class="menu-line">Bookmark</div><div class="menu-line highlight">＋ Add to Home Screen</div></div><figcaption>Choose “Add to Home Screen”.</figcaption></figure><figure><div class="phone-pic center"><div class="app-icon">CC</div><strong>CropChronicle</strong><div class="add-pill">Add</div></div><figcaption>Tap Add, then open the new icon.</figcaption></figure></div>`;
async function buildWizardSteps(){const setup=await getSetup(),farms=await all('farms'),places=await all('places'),events=await all('events');if(farms[0]&&!state.farmId)state.farmId=farms[0].id;if(!state.placeId)state.placeId=places.find((p)=>p.farmId===state.farmId)?.id??null;const steps=[];if(!setup.welcomeDone)steps.push('welcome');if(!setup.installDone)steps.push('install');if(farms.length===0)steps.push('farm');if(places.length===0)steps.push('place');if(events.length===0)steps.push('event');return steps;}
async function startFirstRun(){state.wizardSteps=await buildWizardSteps();state.wizardStep=0;if(state.wizardSteps.length){renderWizard();$('#firstRun').showModal();}}
function renderWizard(){const type=state.wizardSteps[state.wizardStep];$('#wizardCount').textContent=`Step ${state.wizardStep+1} of ${state.wizardSteps.length}`;$('#wizardBack').hidden=state.wizardStep===0;$('#wizardNext').textContent=type==='event'?'Save first event':'Continue';const title=$('#wizardTitle'),body=$('#wizardBody');if(type==='welcome'){title.textContent='Welcome to CropChronicle';body.innerHTML='<p>This is a simple farm notebook and task list that keeps working when your signal does not. Your work stays on this phone.</p>';}if(type==='install'){title.textContent='Add CropChronicle to your Home Screen';body.innerHTML=`<p>For the easiest field use, add it once from Safari.</p>${installPictures}<label><input id="installedCheck" type="checkbox"> I added it, or I understand how to do it later.</label>`;}if(type==='farm'){title.textContent='Name your farm';body.innerHTML='<label>Farm name<input id="wizFarmName" autocomplete="organization" placeholder="Example: Demo Acres"></label><label>Region (optional)<input id="wizFarmRegion" placeholder="Example: Central PA"></label>';}if(type==='place'){title.textContent='Add your first Place';body.innerHTML=`<label>Place name<input id="wizPlaceName" placeholder="Example: North 40"></label><label>Type<select id="wizPlaceType">${PLACE_TYPES.map((t)=>`<option value="${t}">${placeTypeLabel(t)}</option>`).join('')}</select></label><label>Acres (optional)<input id="wizPlaceAcres" inputmode="decimal" placeholder="40"></label>`;}if(type==='event'){title.textContent='Record your first event';body.innerHTML='<label>What happened?<select id="wizEventType"><option>observation</option><option>planting</option><option>application</option><option>field_work</option><option>harvest</option><option>note</option></select></label><label>Short title<input id="wizEventTitle" placeholder="Example: Planted corn"></label><label>Notes<textarea id="wizEventNotes" placeholder="Anything you want to remember"></textarea></label>';}}
$('#wizardBack').addEventListener('click',()=>{if(state.wizardStep>0){state.wizardStep--;renderWizard();}});
$('#wizardNext').addEventListener('click',async()=>{const type=state.wizardSteps[state.wizardStep];try{if(type==='welcome')await setSetup({welcomeDone:true});if(type==='install'){if(!$('#installedCheck')?.checked)return alert('Check the box when you are ready to continue.');await setSetup({installDone:true});}if(type==='farm'){const name=$('#wizFarmName').value.trim();if(!name)return alert('Enter your farm name.');await createFarmFrom(name,$('#wizFarmRegion').value.trim());}if(type==='place'){const name=$('#wizPlaceName').value.trim();if(!name)return alert('Enter a Place name.');await createPlaceFrom(name,$('#wizPlaceType').value,$('#wizPlaceAcres').value.trim());}if(type==='event'){const title=$('#wizEventTitle').value.trim();if(!title)return alert('Add a short title.');await createEventFrom($('#wizEventType').value,title,$('#wizEventNotes').value.trim());}state.wizardSteps=await buildWizardSteps();state.wizardStep=0;if(!state.wizardSteps.length){$('#firstRun').close();switchView('today');return;}renderWizard();}catch(error){alert(error.message||'Could not save.');}});

if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');await refresh();await refreshPlaces();await refreshTimeline();await refreshMap();await refreshAlmanac();wireFarmChrome();refreshFarmChrome();switchView('map');await startFirstRun();
function esc(v){return String(v).replace(/[&<>'"]/g,(ch)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));}
